Mesh<Point, double> result;
std::vector<Point> dual_vertices;
std::map<typename RT::Facet, std::size_t> facet_to_dual_index;

for (auto fit = rt.finite_facets_begin(); fit != rt.finite_facets_end(); ++fit) {
    typename RT::Cell_handle c = fit->first;
    int i = fit->second;
    typename RT::Cell_handle neighbor = c->neighbor(i);
    if (rt.is_infinite(c) || rt.is_infinite(neighbor)) continue;

    double weight_c = rt.weight(c->vertex(0));
    double weight_n = rt.weight(neighbor->vertex(0));
    Point p_c = rt.point(c->vertex(0));
    Point p_n = rt.point(neighbor->vertex(0));

    double squared_distance = (p_c - p_n) * (p_c - p_n);
    double threshold_squared = threshold * threshold;

    if (squared_distance > threshold_squared) continue;

    Point dual_c = p_c - Point(weight_c / squared_distance * (p_c - p_n));
    Point dual_n = p_n - Point(weight_n / squared_distance * (p_n - p_c));

    std::size_t idx_c, idx_n;
    auto it_c = facet_to_dual_index.find(*fit);
    if (it_c == facet_to_dual_index.end()) {
        idx_c = dual_vertices.size();
        dual_vertices.push_back(dual_c);
        facet_to_dual_index[*fit] = idx_c;
    } else {
        idx_c = it_c->second;
    }

    typename RT::Facet neighbor_facet(neighbor, rt.vertex_index(neighbor, c, i));
    auto it_n = facet_to_dual_index.find(neighbor_facet);
    if (it_n == facet_to_dual_index.end()) {
        idx_n = dual_vertices.size();
        dual_vertices.push_back(dual_n);
        facet_to_dual_index[neighbor_facet] = idx_n;
    } else {
        idx_n = it_n->second;
    }

    result.add_edge(idx_c, idx_n, std::sqrt(squared_distance));
}

for (auto fit = rt.finite_facets_begin(); fit != rt.finite_facets_end(); ++fit) {
    typename RT::Cell_handle c = fit->first;
    int i = fit->second;
    if (rt.is_infinite(c)) continue;

    std::vector<Point> face_points;
    for (int j = 0; j < 3; ++j) {
        if (j != i) {
            face_points.push_back(rt.point(c->vertex(j)));
        }
    }

    if (face_points.size() == 3) {
        Point v0 = face_points[0], v1 = face_points[1], v2 = face_points[2];
        double area = std::abs((v1 - v0) * (v2 - v0)) / 2.0;
        result.add_face_area(area);
    }
}

return result;

